// ============================================================================
// DDR4_AXI_apb: APB4 register wrapper around DDR4_AXI_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/DDR4_AXI.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/DDR4_AXI.md
// ============================================================================
module DDR4_AXI_apb #(
  parameter int NCH = 1
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [3:0] s_awid,
  input logic [31:0] s_awaddr,
  input logic [7:0] s_awlen,
  input logic [2:0] s_awsize,
  input logic [1:0] s_awburst,
  input logic s_awvalid,
  output logic s_awready,
  input logic [31:0] s_wdata,
  input logic [3:0] s_wstrb,
  input logic s_wlast,
  input logic s_wvalid,
  output logic s_wready,
  output logic [3:0] s_bid,
  output logic [1:0] s_bresp,
  output logic s_bvalid,
  input logic s_bready,
  input logic [3:0] s_arid,
  input logic [31:0] s_araddr,
  input logic [7:0] s_arlen,
  input logic [2:0] s_arsize,
  input logic [1:0] s_arburst,
  input logic s_arvalid,
  output logic s_arready,
  output logic [3:0] s_rid,
  output logic [31:0] s_rdata,
  output logic [1:0] s_rresp,
  output logic s_rlast,
  output logic s_rvalid,
  input logic s_rready,
  output logic ck_t,
  output logic ck_c,
  output logic [16:0] addr,
  output logic ras_n,
  output logic cas_n,
  output logic we_n,
  inout tri [NCH*16-1:0] dq,
  inout tri [1:0] dqs,
  output logic cke,
  output logic trace_valid,
  output logic [2:0] trace_cmd,
  output logic [31:0] trace_addr
);
  localparam logic [31:0] ID_VALUE = 32'h5D040100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [8:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd9) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [15:0]   c_n_rd;
  logic [15:0]   c_n_wr;
  logic [15:0]   c_n_rmw;
  logic [15:0]   c_n_err;
  logic          c_err_irq;
  DDR4_AXI_top #(.NCH(NCH)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .s_awid(s_awid),
    .s_awaddr(s_awaddr),
    .s_awlen(s_awlen),
    .s_awsize(s_awsize),
    .s_awburst(s_awburst),
    .s_awvalid(s_awvalid),
    .s_awready(s_awready),
    .s_wdata(s_wdata),
    .s_wstrb(s_wstrb),
    .s_wlast(s_wlast),
    .s_wvalid(s_wvalid),
    .s_wready(s_wready),
    .s_bid(s_bid),
    .s_bresp(s_bresp),
    .s_bvalid(s_bvalid),
    .s_bready(s_bready),
    .s_arid(s_arid),
    .s_araddr(s_araddr),
    .s_arlen(s_arlen),
    .s_arsize(s_arsize),
    .s_arburst(s_arburst),
    .s_arvalid(s_arvalid),
    .s_arready(s_arready),
    .s_rid(s_rid),
    .s_rdata(s_rdata),
    .s_rresp(s_rresp),
    .s_rlast(s_rlast),
    .s_rvalid(s_rvalid),
    .s_rready(s_rready),
    .ck_t(ck_t),
    .ck_c(ck_c),
    .addr(addr),
    .ras_n(ras_n),
    .cas_n(cas_n),
    .we_n(we_n),
    .dq(dq),
    .dqs(dqs),
    .cke(cke),
    .trace_valid(trace_valid),
    .trace_cmd(trace_cmd),
    .trace_addr(trace_addr),
    .n_rd(c_n_rd),
    .n_wr(c_n_wr),
    .n_rmw(c_n_rmw),
    .n_err(c_n_err),
    .err_irq(c_err_irq)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_err_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'({c_n_rd});
      10'd6: apb_rdata = 32'({c_n_wr});
      10'd7: apb_rdata = 32'({c_n_rmw});
      10'd8: apb_rdata = 32'({c_n_err});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
